module SurfaceGrammarRecognizerKernel where

import qualified Prelude

__ :: any
__ = Prelude.error "Logical or arity value used"

bool_rec :: a1 -> a1 -> Prelude.Bool -> a1
bool_rec true false b =
  case b of {
   Prelude.True -> true;
   Prelude.False -> false}

andb :: Prelude.Bool -> Prelude.Bool -> Prelude.Bool
andb b1 b2 =
  case b1 of {
   Prelude.True -> b2;
   Prelude.False -> Prelude.False}

orb :: Prelude.Bool -> Prelude.Bool -> Prelude.Bool
orb b1 b2 =
  case b1 of {
   Prelude.True -> Prelude.True;
   Prelude.False -> b2}

data Nat =
   O
 | S Nat

list_rect :: a2 -> (a1 -> ([] a1) -> a2 -> a2) -> ([] a1) -> a2
list_rect nil cons l =
  case l of {
   [] -> nil;
   (:) a l0 -> cons a l0 (list_rect nil cons l0)}

length :: ([] a1) -> Nat
length l =
  case l of {
   [] -> O;
   (:) _ l' -> S (length l')}

app :: ([] a1) -> ([] a1) -> [] a1
app l m =
  case l of {
   [] -> m;
   (:) a l1 -> (:) a (app l1 m)}

data Sumbool =
   Left
 | Right

sumbool_rec :: (() -> a1) -> (() -> a1) -> Sumbool -> a1
sumbool_rec left right s =
  case s of {
   Left -> left __;
   Right -> right __}

add :: Nat -> Nat -> Nat
add n m =
  case n of {
   O -> m;
   S p -> S (add p m)}

mul :: Nat -> Nat -> Nat
mul n m =
  case n of {
   O -> O;
   S p -> add m (mul p m)}

bool_dec :: Prelude.Bool -> Prelude.Bool -> Sumbool
bool_dec b1 b2 =
  bool_rec (\x -> case x of {
                   Prelude.True -> Left;
                   Prelude.False -> Right})
    (\x -> case x of {
            Prelude.True -> Right;
            Prelude.False -> Left})
    b1 b2

eqb :: Prelude.Bool -> Prelude.Bool -> Prelude.Bool
eqb b1 b2 =
  case b1 of {
   Prelude.True -> b2;
   Prelude.False ->
    case b2 of {
     Prelude.True -> Prelude.False;
     Prelude.False -> Prelude.True}}

eqb0 :: Nat -> Nat -> Prelude.Bool
eqb0 n m =
  case n of {
   O -> case m of {
         O -> Prelude.True;
         S _ -> Prelude.False};
   S n' -> case m of {
            O -> Prelude.False;
            S m' -> eqb0 n' m'}}

max :: Nat -> Nat -> Nat
max n m =
  case n of {
   O -> m;
   S n' -> case m of {
            O -> n;
            S m' -> S (max n' m')}}

nth_error :: ([] a1) -> Nat -> Prelude.Maybe a1
nth_error l n =
  case n of {
   O -> case l of {
         [] -> Prelude.Nothing;
         (:) x _ -> Prelude.Just x};
   S n0 -> case l of {
            [] -> Prelude.Nothing;
            (:) _ l' -> nth_error l' n0}}

rev :: ([] a1) -> [] a1
rev l =
  case l of {
   [] -> [];
   (:) x l' -> app (rev l') ((:) x [])}

list_eq_dec :: (a1 -> a1 -> Sumbool) -> ([] a1) -> ([] a1) -> Sumbool
list_eq_dec eq_dec l l' =
  list_rect (\x -> case x of {
                    [] -> Left;
                    (:) _ _ -> Right})
    (\a _ x x0 ->
    case x0 of {
     [] -> Right;
     (:) a0 l0 ->
      sumbool_rec (\_ -> sumbool_rec (\_ -> Left) (\_ -> Right) (x l0))
        (\_ -> Right) (eq_dec a a0)})
    l l'

data Ascii0 =
   Ascii Prelude.Bool Prelude.Bool Prelude.Bool Prelude.Bool Prelude.Bool 
 Prelude.Bool Prelude.Bool Prelude.Bool

ascii_rec :: (Prelude.Bool -> Prelude.Bool -> Prelude.Bool -> Prelude.Bool ->
             Prelude.Bool -> Prelude.Bool -> Prelude.Bool -> Prelude.Bool ->
             a1) -> Ascii0 -> a1
ascii_rec ascii a =
  case a of {
   Ascii b b0 b1 b2 b3 b4 b5 b6 -> ascii b b0 b1 b2 b3 b4 b5 b6}

ascii_dec :: Ascii0 -> Ascii0 -> Sumbool
ascii_dec a b =
  ascii_rec (\b0 b1 b2 b3 b4 b5 b6 b7 x ->
    case x of {
     Ascii b8 b9 b10 b11 b12 b13 b14 b15 ->
      sumbool_rec (\_ ->
        sumbool_rec (\_ ->
          sumbool_rec (\_ ->
            sumbool_rec (\_ ->
              sumbool_rec (\_ ->
                sumbool_rec (\_ ->
                  sumbool_rec (\_ ->
                    sumbool_rec (\_ -> Left) (\_ -> Right) (bool_dec b7 b15))
                    (\_ -> Right) (bool_dec b6 b14))
                  (\_ -> Right) (bool_dec b5 b13))
                (\_ -> Right) (bool_dec b4 b12))
              (\_ -> Right) (bool_dec b3 b11))
            (\_ -> Right) (bool_dec b2 b10))
          (\_ -> Right) (bool_dec b1 b9))
        (\_ -> Right) (bool_dec b0 b8)})
    a b

eqb1 :: Ascii0 -> Ascii0 -> Prelude.Bool
eqb1 a b =
  case a of {
   Ascii a0 a1 a2 a3 a4 a5 a6 a7 ->
    case b of {
     Ascii b0 b1 b2 b3 b4 b5 b6 b7 ->
      case case case case case case case eqb a0 b0 of {
                                     Prelude.True -> eqb a1 b1;
                                     Prelude.False -> Prelude.False} of {
                                Prelude.True -> eqb a2 b2;
                                Prelude.False -> Prelude.False} of {
                           Prelude.True -> eqb a3 b3;
                           Prelude.False -> Prelude.False} of {
                      Prelude.True -> eqb a4 b4;
                      Prelude.False -> Prelude.False} of {
                 Prelude.True -> eqb a5 b5;
                 Prelude.False -> Prelude.False} of {
            Prelude.True -> eqb a6 b6;
            Prelude.False -> Prelude.False} of {
       Prelude.True -> eqb a7 b7;
       Prelude.False -> Prelude.False}}}

data String =
   EmptyString
 | String0 Ascii0 String

string_rec :: a1 -> (Ascii0 -> String -> a1 -> a1) -> String -> a1
string_rec emptyString string s =
  case s of {
   EmptyString -> emptyString;
   String0 a s0 -> string a s0 (string_rec emptyString string s0)}

string_dec :: String -> String -> Sumbool
string_dec s1 s2 =
  string_rec (\x -> case x of {
                     EmptyString -> Left;
                     String0 _ _ -> Right})
    (\a _ x x0 ->
    case x0 of {
     EmptyString -> Right;
     String0 a0 s ->
      sumbool_rec (\_ -> sumbool_rec (\_ -> Left) (\_ -> Right) (x s)) (\_ ->
        Right) (ascii_dec a a0)})
    s1 s2

eqb2 :: String -> String -> Prelude.Bool
eqb2 s1 s2 =
  case s1 of {
   EmptyString ->
    case s2 of {
     EmptyString -> Prelude.True;
     String0 _ _ -> Prelude.False};
   String0 c1 s1' ->
    case s2 of {
     EmptyString -> Prelude.False;
     String0 c2 s2' ->
      case eqb1 c1 c2 of {
       Prelude.True -> eqb2 s1' s2';
       Prelude.False -> Prelude.False}}}

data EbnfExpression =
   ELiteral String
 | ELexicalClass String
 | ENonterminal String
 | ESequence ([] EbnfExpression)
 | EAlternative ([] EbnfExpression)
 | EOptional EbnfExpression
 | ERepetition EbnfExpression

type GrammarRule = (,) String EbnfExpression

