data ConcreteToken =
   TLiteral String
 | TLexical String String

concreteToken_rec :: (String -> a1) -> (String -> String -> a1) ->
                     ConcreteToken -> a1
concreteToken_rec tLiteral tLexical c =
  case c of {
   TLiteral s -> tLiteral s;
   TLexical s s0 -> tLexical s s0}

data SyntaxPathStep =
   AtNonterminal String
 | AtSequence Nat
 | AtAlternative Nat
 | AtOptionalBody
 | AtRepetitionBody

type SyntaxPath = [] SyntaxPathStep

descend :: SyntaxPath -> SyntaxPathStep -> SyntaxPath
descend path step =
  app path ((:) step [])

lookupRule :: String -> ([] GrammarRule) -> Prelude.Maybe EbnfExpression
lookupRule name rules =
  case rules of {
   [] -> Prelude.Nothing;
   (:) g rest ->
    case g of {
     (,) candidate body ->
      case eqb2 name candidate of {
       Prelude.True -> Prelude.Just body;
       Prelude.False -> lookupRule name rest}}}

data ParseTree =
   PTLiteral String
 | PTLexical String String
 | PTNonterminal String ParseTree
 | PTSequence ([] ParseTree)
 | PTAlternative Nat ParseTree
 | PTOptionalNone
 | PTOptionalSome ParseTree
 | PTRepetition ([] ParseTree)

data OracleDecision =
   ChooseAlternative Nat
 | ChooseOptionalAbsent
 | ChooseOptionalPresent
 | ChooseRepetitionStop
 | ChooseRepetitionContinue

type DerivationOracle =
  SyntaxPath -> ([] ConcreteToken) -> Prelude.Maybe OracleDecision

data DerivationGoal =
   GoalExpression SyntaxPath EbnfExpression
 | GoalSequence SyntaxPath Nat ([] EbnfExpression)
 | GoalRepetition SyntaxPath EbnfExpression

data DerivationResult =
   ResultTree ParseTree
 | ResultTrees ([] ParseTree)

data OverlapToken =
   OverlapLiteral String
 | OverlapLexicalClass String
 | OverlapEof
 | OverlapEpsilon

lookup_bool :: String -> ([] ((,) String Prelude.Bool)) -> Prelude.Bool
lookup_bool name facts =
  case facts of {
   [] -> Prelude.False;
   (:) p rest ->
    case p of {
     (,) candidate value ->
      case eqb2 name candidate of {
       Prelude.True -> value;
       Prelude.False -> lookup_bool name rest}}}

overlap_token_eqb :: OverlapToken -> OverlapToken -> Prelude.Bool
overlap_token_eqb left right =
  case left of {
   OverlapLiteral l ->
    case right of {
     OverlapLiteral r -> eqb2 l r;
     _ -> Prelude.False};
   OverlapLexicalClass l ->
    case right of {
     OverlapLexicalClass r -> eqb2 l r;
     _ -> Prelude.False};
   OverlapEof ->
    case right of {
     OverlapEof -> Prelude.True;
     _ -> Prelude.False};
   OverlapEpsilon ->
    case right of {
     OverlapEpsilon -> Prelude.True;
     _ -> Prelude.False}}

token_mem :: OverlapToken -> ([] OverlapToken) -> Prelude.Bool
token_mem token tokens =
  case tokens of {
   [] -> Prelude.False;
   (:) candidate rest ->
    case overlap_token_eqb token candidate of {
     Prelude.True -> Prelude.True;
     Prelude.False -> token_mem token rest}}

token_insert :: OverlapToken -> ([] OverlapToken) -> [] OverlapToken
token_insert token tokens =
  case token_mem token tokens of {
   Prelude.True -> tokens;
   Prelude.False -> (:) token tokens}

token_union :: ([] OverlapToken) -> ([] OverlapToken) -> [] OverlapToken
token_union left right =
  case left of {
   [] -> right;
   (:) token rest -> token_union rest (token_insert token right)}

lookup_tokens :: String -> ([] ((,) String ([] OverlapToken))) -> []
                 OverlapToken
lookup_tokens name facts =
  case facts of {
   [] -> [];
   (:) p rest ->
    case p of {
     (,) candidate value ->
      case eqb2 name candidate of {
       Prelude.True -> value;
       Prelude.False -> lookup_tokens name rest}}}

nullable_expression_fuel :: Nat -> ([] ((,) String Prelude.Bool)) ->
                            EbnfExpression -> Prelude.Maybe Prelude.Bool
nullable_expression_fuel fuel facts expression =
  case fuel of {
   O -> Prelude.Nothing;
   S remaining ->
    case expression of {
     ELiteral _ -> Prelude.Just Prelude.False;
     ELexicalClass _ -> Prelude.Just Prelude.False;
     ENonterminal name -> Prelude.Just (lookup_bool name facts);
     ESequence items ->
      let {
       nullable_sequence_local pending =
         case pending of {
          [] -> Prelude.Just Prelude.True;
          (:) item rest ->
           case nullable_expression_fuel remaining facts item of {
            Prelude.Just head ->
             case nullable_sequence_local rest of {
              Prelude.Just tail -> Prelude.Just (andb head tail);
              Prelude.Nothing -> Prelude.Nothing};
            Prelude.Nothing -> Prelude.Nothing}}}
      in nullable_sequence_local items;
     EAlternative items ->
      let {
       nullable_alternative_local pending =
         case pending of {
          [] -> Prelude.Just Prelude.False;
          (:) item rest ->
           case nullable_expression_fuel remaining facts item of {
            Prelude.Just head ->
             case nullable_alternative_local rest of {
              Prelude.Just tail -> Prelude.Just (orb head tail);
              Prelude.Nothing -> Prelude.Nothing};
            Prelude.Nothing -> Prelude.Nothing}}}
      in nullable_alternative_local items;
     _ -> Prelude.Just Prelude.True}}

