nullable_expression :: ([] ((,) String Prelude.Bool)) -> EbnfExpression ->
                       Prelude.Bool
nullable_expression facts expression =
  case nullable_expression_fuel expression_fuel facts expression of {
   Prelude.Just value -> value;
   Prelude.Nothing -> Prelude.False}

nullable_pass :: ([] GrammarRule) -> ([] ((,) String Prelude.Bool)) -> []
                 ((,) String Prelude.Bool)
nullable_pass rules facts =
  case rules of {
   [] -> [];
   (:) g rest ->
    case g of {
     (,) name expression -> (:) ((,) name
      (nullable_expression facts expression)) (nullable_pass rest facts)}}

initial_nullable :: ([] GrammarRule) -> [] ((,) String Prelude.Bool)
initial_nullable rules =
  case rules of {
   [] -> [];
   (:) g rest ->
    case g of {
     (,) name _ -> (:) ((,) name Prelude.False) (initial_nullable rest)}}

iterate_nullable :: Nat -> ([] GrammarRule) -> ([] ((,) String Prelude.Bool))
                    -> [] ((,) String Prelude.Bool)
iterate_nullable fuel rules facts =
  case fuel of {
   O -> facts;
   S remaining ->
    iterate_nullable remaining rules (nullable_pass rules facts)}

