first_expression_fuel :: Nat -> ([] ((,) String Prelude.Bool)) -> ([]
                         ((,) String ([] OverlapToken))) -> EbnfExpression ->
                         Prelude.Maybe ([] OverlapToken)
first_expression_fuel fuel nullable_facts first_facts expression =
  case fuel of {
   O -> Prelude.Nothing;
   S remaining ->
    case expression of {
     ELiteral literal -> Prelude.Just ((:) (OverlapLiteral literal) []);
     ELexicalClass class0 -> Prelude.Just ((:) (OverlapLexicalClass class0)
      []);
     ENonterminal name -> Prelude.Just (lookup_tokens name first_facts);
     ESequence items ->
      let {
       first_sequence_local pending =
         case pending of {
          [] -> Prelude.Just [];
          (:) item rest ->
           case first_expression_fuel remaining nullable_facts first_facts
                  item of {
            Prelude.Just head ->
             case nullable_expression_fuel remaining nullable_facts item of {
              Prelude.Just b ->
               case b of {
                Prelude.True ->
                 case first_sequence_local rest of {
                  Prelude.Just tail -> Prelude.Just (token_union head tail);
                  Prelude.Nothing -> Prelude.Nothing};
                Prelude.False -> Prelude.Just head};
              Prelude.Nothing -> Prelude.Nothing};
            Prelude.Nothing -> Prelude.Nothing}}}
      in first_sequence_local items;
     EAlternative items ->
      let {
       first_alternative_local pending =
         case pending of {
          [] -> Prelude.Just [];
          (:) item rest ->
           case first_expression_fuel remaining nullable_facts first_facts
                  item of {
            Prelude.Just head ->
             case first_alternative_local rest of {
              Prelude.Just tail -> Prelude.Just (token_union head tail);
              Prelude.Nothing -> Prelude.Nothing};
            Prelude.Nothing -> Prelude.Nothing}}}
      in first_alternative_local items;
     EOptional body ->
      first_expression_fuel remaining nullable_facts first_facts body;
     ERepetition body ->
      first_expression_fuel remaining nullable_facts first_facts body}}

first_expression :: ([] ((,) String Prelude.Bool)) -> ([]
                    ((,) String ([] OverlapToken))) -> EbnfExpression -> []
                    OverlapToken
first_expression nullable_facts first_facts expression =
  case first_expression_fuel expression_fuel nullable_facts first_facts
         expression of {
   Prelude.Just value -> value;
   Prelude.Nothing -> []}

first_pass :: ([] GrammarRule) -> ([] ((,) String Prelude.Bool)) -> ([]
              ((,) String ([] OverlapToken))) -> []
              ((,) String ([] OverlapToken))
first_pass rules nullable_facts first_facts =
  case rules of {
   [] -> [];
   (:) g rest ->
    case g of {
     (,) name expression -> (:) ((,) name
      (first_expression nullable_facts first_facts expression))
      (first_pass rest nullable_facts first_facts)}}

initial_first :: ([] GrammarRule) -> [] ((,) String ([] OverlapToken))
initial_first rules =
  case rules of {
   [] -> [];
   (:) g rest ->
    case g of {
     (,) name _ -> (:) ((,) name []) (initial_first rest)}}

iterate_first :: Nat -> ([] GrammarRule) -> ([] ((,) String Prelude.Bool)) ->
                 ([] ((,) String ([] OverlapToken))) -> []
                 ((,) String ([] OverlapToken))
iterate_first fuel rules nullable_facts first_facts =
  case fuel of {
   O -> first_facts;
   S remaining ->
    iterate_first remaining rules nullable_facts
      (first_pass rules nullable_facts first_facts)}

