parser_rank_lookup :: String -> ([] ((,) String Nat)) -> Nat
parser_rank_lookup name facts =
  case facts of {
   [] -> O;
   (:) p rest ->
    case p of {
     (,) candidate rank ->
      case eqb2 name candidate of {
       Prelude.True -> rank;
       Prelude.False -> parser_rank_lookup name rest}}}

parser_expression_rank_fuel :: Nat -> ([] ((,) String Nat)) -> EbnfExpression
                               -> Prelude.Maybe Nat
parser_expression_rank_fuel fuel facts expression =
  case fuel of {
   O -> Prelude.Nothing;
   S remaining ->
    case expression of {
     ENonterminal name -> Prelude.Just (S (parser_rank_lookup name facts));
     ESequence items ->
      let {
       sequence_rank = let {
                        sequence_rank pending =
                          case pending of {
                           [] -> Prelude.Just (S O);
                           (:) item rest ->
                            case parser_expression_rank_fuel remaining facts
                                   item of {
                             Prelude.Just head_rank ->
                              case nullable_expression
                                     phase1_surface_nullable_facts item of {
                               Prelude.True ->
                                case sequence_rank rest of {
                                 Prelude.Just tail_rank -> Prelude.Just (S
                                  (max head_rank tail_rank));
                                 Prelude.Nothing -> Prelude.Nothing};
                               Prelude.False -> Prelude.Just (S head_rank)};
                             Prelude.Nothing -> Prelude.Nothing}}}
                       in sequence_rank}
      in
      case sequence_rank items of {
       Prelude.Just rank -> Prelude.Just (S rank);
       Prelude.Nothing -> Prelude.Nothing};
     EAlternative items ->
      let {
       alternative_rank = let {
                           alternative_rank pending =
                             case pending of {
                              [] -> Prelude.Just O;
                              (:) item rest ->
                               case parser_expression_rank_fuel remaining
                                      facts item of {
                                Prelude.Just head_rank ->
                                 case alternative_rank rest of {
                                  Prelude.Just tail_rank -> Prelude.Just
                                   (max head_rank tail_rank);
                                  Prelude.Nothing -> Prelude.Nothing};
                                Prelude.Nothing -> Prelude.Nothing}}}
                          in alternative_rank}
      in
      case alternative_rank items of {
       Prelude.Just rank -> Prelude.Just (S rank);
       Prelude.Nothing -> Prelude.Nothing};
     EOptional body ->
      case parser_expression_rank_fuel remaining facts body of {
       Prelude.Just rank -> Prelude.Just (S rank);
       Prelude.Nothing -> Prelude.Nothing};
     ERepetition body ->
      case parser_expression_rank_fuel remaining facts body of {
       Prelude.Just rank -> Prelude.Just (S (S rank));
       Prelude.Nothing -> Prelude.Nothing};
     _ -> Prelude.Just (S O)}}

parser_expression_rank :: ([] ((,) String Nat)) -> EbnfExpression -> Nat
parser_expression_rank facts expression =
  case parser_expression_rank_fuel expression_fuel facts expression of {
   Prelude.Just rank -> rank;
   Prelude.Nothing -> O}

parser_rank_pass :: ([] GrammarRule) -> ([] ((,) String Nat)) -> []
                    ((,) String Nat)
parser_rank_pass rules facts =
  case rules of {
   [] -> [];
   (:) g rest ->
    case g of {
     (,) name body -> (:) ((,) name (parser_expression_rank facts body))
      (parser_rank_pass rest facts)}}

parser_initial_ranks :: ([] GrammarRule) -> [] ((,) String Nat)
parser_initial_ranks rules =
  case rules of {
   [] -> [];
   (:) g rest ->
    case g of {
     (,) name _ -> (:) ((,) name O) (parser_initial_ranks rest)}}

parser_iterate_ranks :: Nat -> ([] GrammarRule) -> ([] ((,) String Nat)) ->
                        [] ((,) String Nat)
parser_iterate_ranks fuel rules facts =
  case fuel of {
   O -> facts;
   S remaining ->
    parser_iterate_ranks remaining rules (parser_rank_pass rules facts)}

