parser_sequence_goal_rank_fuel :: Nat -> ([] ((,) String Nat)) -> ([]
                                  EbnfExpression) -> Prelude.Maybe Nat
parser_sequence_goal_rank_fuel fuel facts items =
  case items of {
   [] -> Prelude.Just (S O);
   (:) item rest ->
    case parser_expression_rank_fuel fuel facts item of {
     Prelude.Just head_rank ->
      case nullable_expression phase1_surface_nullable_facts item of {
       Prelude.True ->
        case parser_sequence_goal_rank_fuel fuel facts rest of {
         Prelude.Just tail_rank -> Prelude.Just (S (max head_rank tail_rank));
         Prelude.Nothing -> Prelude.Nothing};
       Prelude.False -> Prelude.Just (S head_rank)};
     Prelude.Nothing -> Prelude.Nothing}}

parser_repetition_goal_rank_fuel :: Nat -> ([] ((,) String Nat)) ->
                                    EbnfExpression -> Prelude.Maybe Nat
parser_repetition_goal_rank_fuel fuel facts body =
  case parser_expression_rank_fuel fuel facts body of {
   Prelude.Just rank -> Prelude.Just (S rank);
   Prelude.Nothing -> Prelude.Nothing}

parser_expression_goal_rank_options_fuel :: Nat -> ([] ((,) String Nat)) ->
                                            EbnfExpression -> []
                                            (Prelude.Maybe Nat)
parser_expression_goal_rank_options_fuel fuel facts expression =
  case fuel of {
   O -> (:) Prelude.Nothing [];
   S remaining -> (:)
    (parser_expression_rank_fuel (S remaining) facts expression)
    (case expression of {
      ESequence items ->
       let {
        sequence_options pending =
          case pending of {
           [] -> (:) (parser_sequence_goal_rank_fuel remaining facts []) [];
           (:) item rest -> (:)
            (parser_sequence_goal_rank_fuel remaining facts pending)
            (app
              (parser_expression_goal_rank_options_fuel remaining facts item)
              (sequence_options rest))}}
       in sequence_options items;
      EAlternative items ->
       let {
        alternative_options pending =
          case pending of {
           [] -> [];
           (:) item rest ->
            app
              (parser_expression_goal_rank_options_fuel remaining facts item)
              (alternative_options rest)}}
       in alternative_options items;
      EOptional body ->
       parser_expression_goal_rank_options_fuel remaining facts body;
      ERepetition body -> (:)
       (parser_repetition_goal_rank_fuel remaining facts body)
       (parser_expression_goal_rank_options_fuel remaining facts body);
      _ -> []})}

parser_rules_goal_rank_options_fuel :: Nat -> ([] ((,) String Nat)) -> ([]
                                       GrammarRule) -> [] (Prelude.Maybe Nat)
parser_rules_goal_rank_options_fuel fuel facts rules =
  case rules of {
   [] -> [];
   (:) g rest ->
    case g of {
     (,) _ body ->
      app (parser_expression_goal_rank_options_fuel fuel facts body)
        (parser_rules_goal_rank_options_fuel fuel facts rest)}}

phase1_surface_parser_all_goal_rank_options :: [] (Prelude.Maybe Nat)
phase1_surface_parser_all_goal_rank_options =
  app
    (parser_expression_goal_rank_options_fuel expression_fuel
      phase1_surface_parser_rank_facts (ENonterminal phase1_surface_start))
    (parser_rules_goal_rank_options_fuel expression_fuel
      phase1_surface_parser_rank_facts phase1_surface_rules)

parser_option_rank_max :: ([] (Prelude.Maybe Nat)) -> Nat
parser_option_rank_max values =
  case values of {
   [] -> O;
   (:) o rest ->
    case o of {
     Prelude.Just rank -> max rank (parser_option_rank_max rest);
     Prelude.Nothing -> parser_option_rank_max rest}}

phase1_surface_parser_global_goal_rank_bound :: Nat
phase1_surface_parser_global_goal_rank_bound =
  S (parser_option_rank_max phase1_surface_parser_all_goal_rank_options)

phase1_surface_parser_total_fuel :: ([] ConcreteToken) -> Nat
phase1_surface_parser_total_fuel tokens =
  S (mul (S (length tokens)) phase1_surface_parser_global_goal_rank_bound)

syntax_path_step_eqb :: SyntaxPathStep -> SyntaxPathStep -> Prelude.Bool
syntax_path_step_eqb first_step second_step =
  case first_step of {
   AtNonterminal first_name ->
    case second_step of {
     AtNonterminal second_name -> eqb2 first_name second_name;
     _ -> Prelude.False};
   AtSequence first_index ->
    case second_step of {
     AtSequence second_index -> eqb0 first_index second_index;
     _ -> Prelude.False};
   AtAlternative first_index ->
    case second_step of {
     AtAlternative second_index -> eqb0 first_index second_index;
     _ -> Prelude.False};
   AtOptionalBody ->
    case second_step of {
     AtOptionalBody -> Prelude.True;
     _ -> Prelude.False};
   AtRepetitionBody ->
    case second_step of {
     AtRepetitionBody -> Prelude.True;
     _ -> Prelude.False}}

reversed_path_prefixb :: ([] SyntaxPathStep) -> ([] SyntaxPathStep) ->
                         Prelude.Bool
reversed_path_prefixb expected actual =
  case expected of {
   [] -> Prelude.True;
   (:) expected_step expected_rest ->
    case actual of {
     [] -> Prelude.False;
     (:) actual_step actual_rest ->
      andb (syntax_path_step_eqb expected_step actual_step)
        (reversed_path_prefixb expected_rest actual_rest)}}

path_has_suffixb :: SyntaxPath -> SyntaxPath -> Prelude.Bool
path_has_suffixb path suffix =
  reversed_path_prefixb (rev suffix) (rev path)

