phase1_surface_simple_resolver :: DerivationOracle
phase1_surface_simple_resolver path input =
  case path_has_suffixb path provider_declaration_suffix of {
   Prelude.True -> provider_declaration_decision input;
   Prelude.False ->
    case path_has_suffixb path generic_requirement_suffix of {
     Prelude.True -> generic_requirement_decision input;
     Prelude.False ->
      case trailing_comma_repeat_pathb path of {
       Prelude.True -> trailing_comma_repeat_decision input;
       Prelude.False -> Prelude.Nothing}}}

