parenthesis_commit_scan :: Nat -> ([] ConcreteToken) -> Prelude.Maybe
                           ParenthesisCommit
parenthesis_commit_scan depth tokens =
  case tokens of {
   [] -> Prelude.Nothing;
   (:) c rest ->
    case c of {
     TLiteral literal ->
      case delimiter_open_literalb literal of {
       Prelude.True -> parenthesis_commit_scan (S depth) rest;
       Prelude.False ->
        case delimiter_close_literalb literal of {
         Prelude.True ->
          case depth of {
           O ->
            case eqb2 literal (String0 (Ascii Prelude.True Prelude.False
                   Prelude.False Prelude.True Prelude.False Prelude.True
                   Prelude.False Prelude.False) EmptyString) of {
             Prelude.True -> Prelude.Just CommitClose;
             Prelude.False -> Prelude.Nothing};
           S remaining_depth -> parenthesis_commit_scan remaining_depth rest};
         Prelude.False ->
          case andb (eqb0 depth O)
                 (eqb2 literal (String0 (Ascii Prelude.False Prelude.False
                   Prelude.True Prelude.True Prelude.False Prelude.True
                   Prelude.False Prelude.False) EmptyString)) of {
           Prelude.True -> Prelude.Just CommitComma;
           Prelude.False -> parenthesis_commit_scan depth rest}}};
     TLexical _ _ -> parenthesis_commit_scan depth rest}}

primary_expression_decision :: ([] ConcreteToken) -> Prelude.Maybe
                               OracleDecision
primary_expression_decision input =
  case input of {
   [] -> Prelude.Nothing;
   (:) c rest ->
