     TLiteral first_literal ->
      case eqb2 first_literal (String0 (Ascii Prelude.False Prelude.False
             Prelude.False Prelude.True Prelude.False Prelude.True
             Prelude.False Prelude.False) EmptyString) of {
       Prelude.True ->
        case parenthesis_commit_scan O rest of {
         Prelude.Just p ->
          case p of {
           CommitComma -> Prelude.Just (ChooseAlternative O);
           CommitClose -> Prelude.Just (ChooseAlternative (S O))};
         Prelude.Nothing -> Prelude.Nothing};
       Prelude.False -> Prelude.Nothing};
     TLexical _ _ -> Prelude.Nothing}}

