                Prelude.True Prelude.False) (String0 (Ascii Prelude.False
                Prelude.False Prelude.False Prelude.True Prelude.False
                Prelude.True Prelude.True Prelude.False) (String0 (Ascii
                Prelude.True Prelude.False Prelude.True Prelude.False
                Prelude.False Prelude.True Prelude.True Prelude.False)
                (String0 (Ascii Prelude.False Prelude.True Prelude.True
                Prelude.True Prelude.False Prelude.True Prelude.True
                Prelude.False) EmptyString)))))
              (orb
                (eqb2 literal (String0 (Ascii Prelude.True Prelude.True
                  Prelude.True Prelude.False Prelude.True Prelude.True
                  Prelude.True Prelude.False) (String0 (Ascii Prelude.True
                  Prelude.False Prelude.False Prelude.True Prelude.False
                  Prelude.True Prelude.True Prelude.False) (String0 (Ascii
                  Prelude.False Prelude.False Prelude.True Prelude.False
                  Prelude.True Prelude.True Prelude.True Prelude.False)
                  (String0 (Ascii Prelude.False Prelude.False Prelude.False
                  Prelude.True Prelude.False Prelude.True Prelude.True
                  Prelude.False) (String0 (Ascii Prelude.True Prelude.False
                  Prelude.False Prelude.True Prelude.False Prelude.True
                  Prelude.True Prelude.False) (String0 (Ascii Prelude.False
                  Prelude.True Prelude.True Prelude.True Prelude.False
                  Prelude.True Prelude.True Prelude.False) EmptyString)))))))
                (orb
                  (eqb2 literal (String0 (Ascii Prelude.True Prelude.True
                    Prelude.False Prelude.True Prelude.True Prelude.True
                    Prelude.True Prelude.False) EmptyString))
                  (eqb2 literal (String0 (Ascii Prelude.True Prelude.False
                    Prelude.True Prelude.True Prelude.True Prelude.True
                    Prelude.True Prelude.False) EmptyString)))))))))

relation_commit_scan :: Nat -> ([] ConcreteToken) -> Prelude.Bool
relation_commit_scan depth tokens =
  case tokens of {
   [] -> Prelude.False;
   (:) c rest ->
    case c of {
     TLiteral literal ->
      case andb (eqb0 depth O) (proposition_atom_boundary_literalb literal) of {
       Prelude.True -> Prelude.False;
       Prelude.False ->
        case delimiter_open_literalb literal of {
         Prelude.True -> relation_commit_scan (S depth) rest;
         Prelude.False ->
          case delimiter_close_literalb literal of {
           Prelude.True ->
            case depth of {
             O -> Prelude.False;
             S remaining_depth -> relation_commit_scan remaining_depth rest};
           Prelude.False ->
            case eqb0 depth O of {
             Prelude.True ->
              case relation_operator_literalb literal of {
               Prelude.True -> Prelude.True;
               Prelude.False -> relation_commit_scan depth rest};
             Prelude.False -> relation_commit_scan depth rest}}}};
     TLexical _ _ -> relation_commit_scan depth rest}}

proposition_atom_decision :: ([] ConcreteToken) -> Prelude.Maybe
                             OracleDecision
proposition_atom_decision input =
  case input of {
   [] -> Prelude.Nothing;
   (:) c rest ->
    case c of {
     TLiteral first_literal ->
      case eqb2 first_literal (String0 (Ascii Prelude.False Prelude.False
             Prelude.False Prelude.True Prelude.False Prelude.True
             Prelude.False Prelude.False) EmptyString) of {
       Prelude.True ->
        case relation_commit_scan (S O) rest of {
         Prelude.True -> Prelude.Just (ChooseAlternative O);
         Prelude.False -> Prelude.Just (ChooseAlternative (S O))};
       Prelude.False ->
        case eqb2 first_literal (String0 (Ascii Prelude.False Prelude.False
               Prelude.True Prelude.False Prelude.True Prelude.True
               Prelude.True Prelude.False) (String0 (Ascii Prelude.False
               Prelude.True Prelude.False Prelude.False Prelude.True
               Prelude.True Prelude.True Prelude.False) (String0 (Ascii
               Prelude.True Prelude.False Prelude.True Prelude.False
               Prelude.True Prelude.True Prelude.True Prelude.False) (String0
               (Ascii Prelude.True Prelude.False Prelude.True Prelude.False
               Prelude.False Prelude.True Prelude.True Prelude.False)
               EmptyString)))) of {
         Prelude.True ->
          case relation_commit_scan O rest of {
           Prelude.True -> Prelude.Just (ChooseAlternative O);
           Prelude.False -> Prelude.Just (ChooseAlternative (S (S O)))};
         Prelude.False ->
          case eqb2 first_literal (String0 (Ascii Prelude.False Prelude.True
                 Prelude.True Prelude.False Prelude.False Prelude.True
                 Prelude.True Prelude.False) (String0 (Ascii Prelude.True
                 Prelude.False Prelude.False Prelude.False Prelude.False
                 Prelude.True Prelude.True Prelude.False) (String0 (Ascii
                 Prelude.False Prelude.False Prelude.True Prelude.True
                 Prelude.False Prelude.True Prelude.True Prelude.False)
                 (String0 (Ascii Prelude.True Prelude.True Prelude.False
                 Prelude.False Prelude.True Prelude.True Prelude.True
                 Prelude.False) (String0 (Ascii Prelude.True Prelude.False
                 Prelude.True Prelude.False Prelude.False Prelude.True
                 Prelude.True Prelude.False) EmptyString))))) of {
           Prelude.True ->
            case relation_commit_scan O rest of {
             Prelude.True -> Prelude.Just (ChooseAlternative O);
             Prelude.False -> Prelude.Just (ChooseAlternative (S (S (S O))))};
           Prelude.False -> Prelude.Nothing}}};
     TLexical class_name _ ->
      case eqb2 class_name (String0 (Ascii Prelude.True Prelude.False
             Prelude.False Prelude.True Prelude.False Prelude.False
             Prelude.True Prelude.False) (String0 (Ascii Prelude.False
             Prelude.False Prelude.True Prelude.False Prelude.False
             Prelude.False Prelude.True Prelude.False) (String0 (Ascii
             Prelude.True Prelude.False Prelude.True Prelude.False
             Prelude.False Prelude.False Prelude.True Prelude.False) (String0
             (Ascii Prelude.False Prelude.True Prelude.True Prelude.True
             Prelude.False Prelude.False Prelude.True Prelude.False) (String0
             (Ascii Prelude.False Prelude.False Prelude.True Prelude.False
             Prelude.True Prelude.False Prelude.True Prelude.False) (String0
             (Ascii Prelude.True Prelude.False Prelude.False Prelude.True
             Prelude.False Prelude.False Prelude.True Prelude.False) (String0
             (Ascii Prelude.False Prelude.True Prelude.True Prelude.False
             Prelude.False Prelude.False Prelude.True Prelude.False) (String0
             (Ascii Prelude.True Prelude.False Prelude.False Prelude.True
             Prelude.False Prelude.False Prelude.True Prelude.False) (String0
             (Ascii Prelude.True Prelude.False Prelude.True Prelude.False
             Prelude.False Prelude.False Prelude.True Prelude.False) (String0
             (Ascii Prelude.False Prelude.True Prelude.False Prelude.False
             Prelude.True Prelude.False Prelude.True Prelude.False)
             EmptyString)))))))))) of {
       Prelude.True ->
        case relation_commit_scan O rest of {
         Prelude.True -> Prelude.Just (ChooseAlternative O);
         Prelude.False -> Prelude.Just (ChooseAlternative (S (S (S (S O)))))};
       Prelude.False -> Prelude.Nothing}}}

phase1_surface_structural_resolver :: DerivationOracle
phase1_surface_structural_resolver path input =
  case path_has_suffixb path pattern_suffix of {
   Prelude.True -> pattern_decision input;
   Prelude.False ->
    case path_has_suffixb path primary_expression_suffix of {
     Prelude.True -> primary_expression_decision input;
     Prelude.False ->
      case path_has_suffixb path proposition_atom_suffix of {
       Prelude.True -> proposition_atom_decision input;
       Prelude.False ->
        case path_has_suffixb path static_argument_suffix of {
         Prelude.True -> static_argument_decision input;
         Prelude.False -> Prelude.Nothing}}}}

phase1_surface_certified_overlap_resolver :: DerivationOracle
phase1_surface_certified_overlap_resolver path input =
  case phase1_surface_simple_resolver path input of {
   Prelude.Just decision -> Prelude.Just decision;
   Prelude.Nothing -> phase1_surface_structural_resolver path input}

concrete_token_shape :: ConcreteToken -> OverlapToken
concrete_token_shape token =
  case token of {
   TLiteral literal -> OverlapLiteral literal;
   TLexical class_name _ -> OverlapLexicalClass class_name}

expression_starts_inputb :: EbnfExpression -> ([] ConcreteToken) ->
                            Prelude.Bool
expression_starts_inputb expression input =
  case input of {
   [] -> nullable_expression phase1_surface_nullable_facts expression;
   (:) token _ ->
    token_mem (concrete_token_shape token)
      (first_expression phase1_surface_nullable_facts
        phase1_surface_first_facts expression)}

first_matching_alternative :: Nat -> ([] EbnfExpression) -> ([]
                              ConcreteToken) -> Prelude.Maybe Nat
first_matching_alternative index items input =
  case items of {
   [] -> Prelude.Nothing;
   (:) item rest ->
    case expression_starts_inputb item input of {
     Prelude.True -> Prelude.Just index;
     Prelude.False -> first_matching_alternative (S index) rest input}}

predictive_fallback_decision :: EbnfExpression -> ([] ConcreteToken) ->
                                Prelude.Maybe OracleDecision
predictive_fallback_decision expression input =
  case expression of {
   EAlternative items ->
    case first_matching_alternative O items input of {
     Prelude.Just index -> Prelude.Just (ChooseAlternative index);
     Prelude.Nothing -> Prelude.Nothing};
   EOptional body ->
    case expression_starts_inputb body input of {
     Prelude.True -> Prelude.Just ChooseOptionalPresent;
     Prelude.False -> Prelude.Just ChooseOptionalAbsent};
   ERepetition body ->
    case expression_starts_inputb body input of {
     Prelude.True -> Prelude.Just ChooseRepetitionContinue;
     Prelude.False -> Prelude.Just ChooseRepetitionStop};
   _ -> Prelude.Nothing}

step_expression :: ([] GrammarRule) -> EbnfExpression -> SyntaxPathStep ->
                   Prelude.Maybe EbnfExpression
step_expression rules expression step =
  case step of {
   AtNonterminal wanted ->
    case expression of {
     ENonterminal actual ->
      case eqb2 wanted actual of {
       Prelude.True -> lookupRule wanted rules;
       Prelude.False -> Prelude.Nothing};
     _ -> Prelude.Nothing};
   AtSequence index ->
    case expression of {
     ESequence items -> nth_error items index;
     _ -> Prelude.Nothing};
   AtAlternative index ->
    case expression of {
     EAlternative items -> nth_error items index;
     _ -> Prelude.Nothing};
   AtOptionalBody ->
    case expression of {
     EOptional body -> Prelude.Just body;
     _ -> Prelude.Nothing};
   AtRepetitionBody ->
    case expression of {
     ERepetition body -> Prelude.Just body;
     _ -> Prelude.Nothing}}

expression_at_path :: ([] GrammarRule) -> EbnfExpression -> SyntaxPath ->
                      Prelude.Maybe EbnfExpression
expression_at_path rules expression path =
  case path of {
   [] -> Prelude.Just expression;
   (:) step rest ->
    case step_expression rules expression step of {
     Prelude.Just next -> expression_at_path rules next rest;
     Prelude.Nothing -> Prelude.Nothing}}

phase1_surface_root_expression :: EbnfExpression
phase1_surface_root_expression =
  ENonterminal phase1_surface_start

phase1_surface_expression_at_path :: SyntaxPath -> Prelude.Maybe
                                     EbnfExpression
phase1_surface_expression_at_path path =
  expression_at_path phase1_surface_rules phase1_surface_root_expression path

phase1_surface_predictive_oracle :: DerivationOracle
phase1_surface_predictive_oracle path input =
  case phase1_surface_certified_overlap_resolver path input of {
   Prelude.Just decision -> Prelude.Just decision;
   Prelude.Nothing ->
    case phase1_surface_expression_at_path path of {
     Prelude.Just expression -> predictive_fallback_decision expression input;
     Prelude.Nothing -> Prelude.Nothing}}

concrete_token_eq_dec :: ConcreteToken -> ConcreteToken -> Sumbool
concrete_token_eq_dec left right =
  concreteToken_rec (\s x ->
    case x of {
     TLiteral s0 -> sumbool_rec (\_ -> Left) (\_ -> Right) (string_dec s s0);
     TLexical _ _ -> Right}) (\s s0 x ->
    case x of {
     TLiteral _ -> Right;
     TLexical s1 s2 ->
      sumbool_rec (\_ ->
        sumbool_rec (\_ -> Left) (\_ -> Right) (string_dec s0 s2)) (\_ ->
        Right) (string_dec s s1)})
    left right

oracle_parse_fuel :: Nat -> DerivationOracle -> ([] GrammarRule) ->
                     DerivationGoal -> ([] ConcreteToken) -> Prelude.Maybe
                     ((,) ([] ConcreteToken) DerivationResult)
oracle_parse_fuel fuel oracle rules goal input =
  case fuel of {
   O -> Prelude.Nothing;
   S remaining ->
    case goal of {
     GoalExpression path expression ->
      case expression of {
       ELiteral literal ->
        case input of {
         [] -> Prelude.Nothing;
         (:) c tail ->
          case c of {
           TLiteral actual ->
            case eqb2 actual literal of {
             Prelude.True -> Prelude.Just ((,) tail (ResultTree (PTLiteral
              literal)));
             Prelude.False -> Prelude.Nothing};
           TLexical _ _ -> Prelude.Nothing}};
       ELexicalClass class0 ->
        case input of {
         [] -> Prelude.Nothing;
         (:) c tail ->
          case c of {
           TLiteral _ -> Prelude.Nothing;
           TLexical actual_class lexeme ->
            case eqb2 actual_class class0 of {
             Prelude.True -> Prelude.Just ((,) tail (ResultTree (PTLexical
              class0 lexeme)));
             Prelude.False -> Prelude.Nothing}}};
       ENonterminal name ->
        case lookupRule name rules of {
         Prelude.Just body ->
          case oracle_parse_fuel remaining oracle rules (GoalExpression
                 (descend path (AtNonterminal name)) body) input of {
           Prelude.Just p ->
            case p of {
             (,) rest d ->
              case d of {
               ResultTree tree -> Prelude.Just ((,) rest (ResultTree
                (PTNonterminal name tree)));
               ResultTrees _ -> Prelude.Nothing}};
           Prelude.Nothing -> Prelude.Nothing};
         Prelude.Nothing -> Prelude.Nothing};
       ESequence items ->
        case oracle_parse_fuel remaining oracle rules (GoalSequence path O
               items) input of {
         Prelude.Just p ->
          case p of {
           (,) rest d ->
            case d of {
             ResultTree _ -> Prelude.Nothing;
             ResultTrees trees -> Prelude.Just ((,) rest (ResultTree
              (PTSequence trees)))}};
         Prelude.Nothing -> Prelude.Nothing};
       EAlternative items ->
        case oracle path input of {
         Prelude.Just o ->
          case o of {
           ChooseAlternative index ->
            case nth_error items index of {
             Prelude.Just item ->
              case oracle_parse_fuel remaining oracle rules (GoalExpression
                     (descend path (AtAlternative index)) item) input of {
               Prelude.Just p ->
                case p of {
                 (,) rest d ->
                  case d of {
                   ResultTree tree -> Prelude.Just ((,) rest (ResultTree
                    (PTAlternative index tree)));
                   ResultTrees _ -> Prelude.Nothing}};
               Prelude.Nothing -> Prelude.Nothing};
             Prelude.Nothing -> Prelude.Nothing};
           _ -> Prelude.Nothing};
         Prelude.Nothing -> Prelude.Nothing};
       EOptional body ->
        case oracle path input of {
         Prelude.Just o ->
          case o of {
           ChooseOptionalAbsent -> Prelude.Just ((,) input (ResultTree
            PTOptionalNone));
           ChooseOptionalPresent ->
            case oracle_parse_fuel remaining oracle rules (GoalExpression
                   (descend path AtOptionalBody) body) input of {
             Prelude.Just p ->
              case p of {
               (,) rest d ->
                case d of {
                 ResultTree tree -> Prelude.Just ((,) rest (ResultTree
                  (PTOptionalSome tree)));
                 ResultTrees _ -> Prelude.Nothing}};
             Prelude.Nothing -> Prelude.Nothing};
           _ -> Prelude.Nothing};
         Prelude.Nothing -> Prelude.Nothing};
       ERepetition body ->
        case oracle_parse_fuel remaining oracle rules (GoalRepetition path
               body) input of {
         Prelude.Just p ->
          case p of {
           (,) rest d ->
            case d of {
             ResultTree _ -> Prelude.Nothing;
             ResultTrees trees -> Prelude.Just ((,) rest (ResultTree
              (PTRepetition trees)))}};
         Prelude.Nothing -> Prelude.Nothing}};
     GoalSequence path index items ->
      case items of {
       [] -> Prelude.Just ((,) input (ResultTrees []));
       (:) item tail_items ->
        case oracle_parse_fuel remaining oracle rules (GoalExpression
               (descend path (AtSequence index)) item) input of {
         Prelude.Just p ->
          case p of {
           (,) middle d ->
            case d of {
             ResultTree tree ->
              case oracle_parse_fuel remaining oracle rules (GoalSequence
                     path (S index) tail_items) middle of {
               Prelude.Just p0 ->
                case p0 of {
                 (,) rest d0 ->
                  case d0 of {
                   ResultTree _ -> Prelude.Nothing;
                   ResultTrees trees -> Prelude.Just ((,) rest (ResultTrees
                    ((:) tree trees)))}};
               Prelude.Nothing -> Prelude.Nothing};
             ResultTrees _ -> Prelude.Nothing}};
         Prelude.Nothing -> Prelude.Nothing}};
     GoalRepetition path body ->
      case oracle path input of {
       Prelude.Just o ->
        case o of {
         ChooseRepetitionStop -> Prelude.Just ((,) input (ResultTrees []));
         ChooseRepetitionContinue ->
          case oracle_parse_fuel remaining oracle rules (GoalExpression
                 (descend path AtRepetitionBody) body) input of {
           Prelude.Just p ->
            case p of {
             (,) middle d ->
              case d of {
               ResultTree tree ->
                case list_eq_dec concrete_token_eq_dec input middle of {
                 Left -> Prelude.Nothing;
                 Right ->
                  case oracle_parse_fuel remaining oracle rules
                         (GoalRepetition path body) middle of {
                   Prelude.Just p0 ->
                    case p0 of {
                     (,) rest d0 ->
                      case d0 of {
                       ResultTree _ -> Prelude.Nothing;
                       ResultTrees trees -> Prelude.Just ((,) rest
                        (ResultTrees ((:) tree trees)))}};
                   Prelude.Nothing -> Prelude.Nothing}};
               ResultTrees _ -> Prelude.Nothing}};
           Prelude.Nothing -> Prelude.Nothing};
         _ -> Prelude.Nothing};
       Prelude.Nothing -> Prelude.Nothing}}}

phase1_surface_predictive_parse_fuel :: Nat -> ([] ConcreteToken) ->
                                        Prelude.Maybe
                                        ((,) ([] ConcreteToken)
                                        DerivationResult)
phase1_surface_predictive_parse_fuel fuel tokens =
  oracle_parse_fuel fuel phase1_surface_predictive_oracle
    phase1_surface_rules (GoalExpression [] (ENonterminal
    phase1_surface_start)) tokens

phase1_surface_reference_parse :: ([] ConcreteToken) -> Prelude.Maybe
                                  ((,) ([] ConcreteToken) DerivationResult)
phase1_surface_reference_parse tokens =
  phase1_surface_predictive_parse_fuel
    (phase1_surface_parser_total_fuel tokens) tokens

phase1_surface_reference_accepts :: ([] ConcreteToken) -> Prelude.Bool
phase1_surface_reference_accepts tokens =
  case phase1_surface_reference_parse tokens of {
   Prelude.Just p ->
    case p of {
     (,) l d ->
      case l of {
       [] ->
        case d of {
         ResultTree _ -> Prelude.True;
         ResultTrees _ -> Prelude.False};
       (:) _ _ -> Prelude.False}};
   Prelude.Nothing -> Prelude.False}

